# strategic-flow-backend/src/modules/crm/scheduler.pyimport asyncioimport loggingfrom datetime import datetime, timedeltafrom core.database import get_dbfrom .automation import on_next_action_due, on_client_sla_breach, on_opportunity_stage_changedlogger = logging.getLogger("crm_scheduler")CHECK_INTERVAL = 60 * 60 * 24  # 24hasync def check_next_actions(tenant_id: str):    db = await get_db()    today = datetime.today().date()    interactions = await db.fetch("""        SELECT id FROM interactions         WHERE tenant_id = $1 AND next_action_date = $2    """, tenant_id, today)    for i in interactions:        await on_next_action_due(i["id"], tenant_id)async def check_client_sla(tenant_id: str):    db = await get_db()    cutoff = datetime.today() - timedelta(days=30)    clients = await db.fetch("""        SELECT id FROM clients         WHERE tenant_id = $1 AND last_interaction < $2    """, tenant_id, cutoff)    for c in clients:        await on_client_sla_breach(c["id"], tenant_id)async def check_opportunity_stage_changes(tenant_id: str):    db = await get_db()    # Exemplo: buscar oportunidades fechadas hoje    today = datetime.today().date()    opps = await db.fetch("""        SELECT id, stage, updated_at FROM opportunities        WHERE tenant_id = $1 AND stage = 'fechado_positivo' AND DATE(updated_at) = $2    """, tenant_id, today)    for o in opps:        await on_opportunity_stage_changed(o["id"], "diagnostico", "fechado_positivo", tenant_id)async def run_scheduler(tenant_id: str = "default-tenant"):    while True:        logger.info("🔄 Rodando scheduler CRM...")        await check_next_actions(tenant_id)        await check_client_sla(tenant_id)        await check_opportunity_stage_changes(tenant_id)        logger.info("✅ Scheduler CRM finalizado")        await asyncio.sleep(CHECK_INTERVAL)